import React from "react";
import Sidebar from "./components/Sidebar";
import Settings from "./pages/Settings";

function App() {
  return (
    <div
      style={{
        display: "flex",
        background: "#0f172a",
        color: "white",
        minHeight: "100vh"
      }}
    >
      <Sidebar />
      <Settings />
    </div>
  );
}

export default App;
